package com.smartrecruit.identity.config;
import com.nimbusds.jose.jwk.source.ImmutableSecret; import com.smartrecruit.identity.domain.UserAccount.Status; import com.smartrecruit.identity.repo.UserRepository; import java.nio.charset.StandardCharsets; import java.util.Collections; import java.util.stream.Collectors; import javax.crypto.spec.SecretKeySpec; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.security.authentication.*; import org.springframework.security.authentication.dao.DaoAuthenticationProvider; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.oauth2.jose.jws.MacAlgorithm; import org.springframework.security.oauth2.jwt.*; import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter; import org.springframework.security.web.SecurityFilterChain;
@Configuration @EnableMethodSecurity public class SecurityConfig {
 @Bean BCryptPasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);} @Bean UserDetailsService users(UserRepository repo){return email->{var u=repo.findByEmailIgnoreCase(email).orElseThrow(()->new UsernameNotFoundException("Invalid credentials"));return User.withUsername(u.email).password(u.passwordHash).roles(u.role.name()).disabled(u.status!=Status.ACTIVE).build();};}
 @Bean AuthenticationManager authenticationManager(UserDetailsService uds,BCryptPasswordEncoder encoder){var p=new DaoAuthenticationProvider();p.setUserDetailsService(uds);p.setPasswordEncoder(encoder);return new ProviderManager(p);}
 @Bean JwtEncoder jwtEncoder(@Value("${identity.jwt.secret}")String secret){return new NimbusJwtEncoder(new ImmutableSecret<>(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256")));}
 @Bean JwtDecoder jwtDecoder(@Value("${identity.jwt.secret}")String secret,@Value("${identity.jwt.issuer}")String issuer){var d=NimbusJwtDecoder.withSecretKey(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256")).macAlgorithm(MacAlgorithm.HS256).build();d.setJwtValidator(JwtValidators.createDefaultWithIssuer(issuer));return d;}
 @Bean SecurityFilterChain chain(HttpSecurity http)throws Exception{var c=new JwtAuthenticationConverter();c.setJwtGrantedAuthoritiesConverter(jwt->{var roles=jwt.getClaimAsStringList("roles");return roles==null?java.util.Collections.emptyList():roles.stream().map(r->new SimpleGrantedAuthority("ROLE_"+r)).collect(java.util.stream.Collectors.toList());});return http.csrf(x->x.disable()).sessionManagement(x->x.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(x->x.requestMatchers("/api/v1/auth/**","/swagger-ui/**","/v3/api-docs/**","/actuator/health").permitAll().anyRequest().authenticated()).oauth2ResourceServer(x->x.jwt(j->j.jwtAuthenticationConverter(c))).build();}
}
